=== FILE: axil_timer.v ===
// axil_timer: AXI4-Lite down-counting timer with one-shot / periodic modes
// and a level interrupt. Implements interface_spec.md per microarchitecture.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL   = 2'd0;
  localparam [1:0] IDX_LOAD   = 2'd1;
  localparam [1:0] IDX_COUNT  = 2'd2;
  localparam [1:0] IDX_STATUS = 2'd3;

  // Channel state
  reg                  aw_held;
  reg                  w_held;
  reg [ADDR_WIDTH-1:0] awaddr_q;
  reg [31:0]           wdata_q;
  reg [3:0]            wstrb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [31:0]           rdata_q;
  reg [1:0]            rresp_q;

  // Timer state
  reg                  en;
  reg                  ie;
  reg                  mode;
  reg                  expired;
  reg [31:0]           load;
  reg [31:0]           count;

  // Write channel
  wire                  awready_w = !aw_held && !bvalid_q;
  wire                  wready_w  = !w_held && !bvalid_q;
  wire                  aw_hs     = s_axil_awvalid && awready_w;
  wire                  w_hs      = s_axil_wvalid && wready_w;
  wire                  do_write  = (aw_held || aw_hs) && (w_held || w_hs);
  wire [ADDR_WIDTH-1:0] wr_addr   = aw_held ? awaddr_q : s_axil_awaddr;
  wire [31:0]           wr_data   = w_held ? wdata_q : s_axil_wdata;
  wire [3:0]            wr_strb   = w_held ? wstrb_q : s_axil_wstrb;
  wire                  wr_mapped = (wr_addr[1:0] == 2'b00) &&
                                    ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0]            wr_idx    = wr_addr[3:2];
  wire                  wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);
  wire                  ctrl_we   = do_write && wr_ok && (wr_idx == IDX_CTRL) && wr_strb[0];
  wire                  load_we   = do_write && wr_ok && (wr_idx == IDX_LOAD);
  wire                  stat_clr  = do_write && wr_ok && (wr_idx == IDX_STATUS) &&
                                    wr_strb[0] && wr_data[0];

  // Read channel
  wire                  ar_hs     = s_axil_arvalid && !rvalid_q;
  wire                  rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                                    ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0]            rd_idx    = s_axil_araddr[3:2];
  reg  [31:0]           rd_value;

  always @* begin
    rd_value = 32'd0;
    case (rd_idx)
      IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
      IDX_LOAD:   rd_value = load;
      IDX_COUNT:  rd_value = count;
      IDX_STATUS: rd_value = {31'd0, expired};
      default:    rd_value = 32'd0;
    endcase
  end

  // Timer end of count: EN set and COUNT at 1 or 0
  wire count_end = en && (count <= 32'd1);

  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held  <= 1'b0;
      w_held   <= 1'b0;
      awaddr_q <= {ADDR_WIDTH{1'b0}};
      wdata_q  <= 32'd0;
      wstrb_q  <= 4'd0;
      bvalid_q <= 1'b0;
      bresp_q  <= RESP_OKAY;
      rvalid_q <= 1'b0;
      rdata_q  <= 32'd0;
      rresp_q  <= RESP_OKAY;
      en       <= 1'b0;
      ie       <= 1'b0;
      mode     <= 1'b0;
      expired  <= 1'b0;
      load     <= 32'd0;
      count    <= 32'd0;
    end else begin
      // ---- write channel ----
      if (aw_hs) begin
        awaddr_q <= s_axil_awaddr;
      end
      if (w_hs) begin
        wdata_q <= s_axil_wdata;
        wstrb_q <= s_axil_wstrb;
      end
      if (do_write) begin
        aw_held  <= 1'b0;
        w_held   <= 1'b0;
        bvalid_q <= 1'b1;
        bresp_q  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
      end else begin
        if (aw_hs) begin
          aw_held <= 1'b1;
        end
        if (w_hs) begin
          w_held <= 1'b1;
        end
        if (bvalid_q && s_axil_bready) begin
          bvalid_q <= 1'b0;
        end
      end

      // ---- read channel ----
      if (ar_hs) begin
        rvalid_q <= 1'b1;
        rdata_q  <= rd_mapped ? rd_value : 32'd0;
        rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
      end else if (rvalid_q && s_axil_rready) begin
        rvalid_q <= 1'b0;
      end

      // ---- 1. count step ----
      if (count_end) begin
        if (mode) begin
          count <= load;
        end else begin
          count <= 32'd0;
          en    <= 1'b0;
        end
      end else if (en) begin
        count <= count - 32'd1;
      end

      // ---- 2. expired: clear, then set (count end wins) ----
      if (stat_clr) begin
        expired <= 1'b0;
      end
      if (count_end) begin
        expired <= 1'b1;
      end

      // ---- 3. CTRL write (wins for en and count) ----
      if (ctrl_we) begin
        ie   <= wr_data[1];
        mode <= wr_data[2];
        if (wr_data[0]) begin
          en    <= 1'b1;
          count <= load;
        end else begin
          en <= 1'b0;
        end
      end

      // ---- 4. LOAD write, byte merge ----
      if (load_we) begin
        if (wr_strb[0]) load[7:0]   <= wr_data[7:0];
        if (wr_strb[1]) load[15:8]  <= wr_data[15:8];
        if (wr_strb[2]) load[23:16] <= wr_data[23:16];
        if (wr_strb[3]) load[31:24] <= wr_data[31:24];
      end
    end
  end

  assign s_axil_awready = awready_w;
  assign s_axil_wready  = wready_w;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_arready = !rvalid_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rdata   = rdata_q;
  assign s_axil_rresp   = rresp_q;
  assign irq            = expired && ie;

endmodule
=== END FILE ===
