`timescale 1ns/1ps
// Self-checking testbench for axil_timer. Two lanes: ADDR_WIDTH 4 and 8.
module axil_timer_tb;
  localparam [1:0] OK  = 2'b00;
  localparam [1:0] ERR = 2'b10;

  reg        clk;
  reg        aresetn;
  reg        lane;
  reg [7:0]  awaddr;
  reg        awvalid;
  reg [31:0] wdata;
  reg [3:0]  wstrb;
  reg        wvalid;
  reg        bready;
  reg [7:0]  araddr;
  reg        arvalid;
  reg        rready;

  wire awready4, wready4, bvalid4, arready4, rvalid4, irq4;
  wire [1:0] bresp4, rresp4;
  wire [31:0] rdata4;
  wire awready8, wready8, bvalid8, arready8, rvalid8, irq8;
  wire [1:0] bresp8, rresp8;
  wire [31:0] rdata8;

  axil_timer #(.ADDR_WIDTH(4)) dut4 (
    .aclk(clk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid & ~lane), .s_axil_awready(awready4),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & ~lane), .s_axil_wready(wready4),
    .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready & ~lane),
    .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid & ~lane), .s_axil_arready(arready4),
    .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready & ~lane),
    .irq(irq4));

  axil_timer #(.ADDR_WIDTH(8)) dut8 (
    .aclk(clk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid & lane), .s_axil_awready(awready8),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & lane), .s_axil_wready(wready8),
    .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready & lane),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid & lane), .s_axil_arready(arready8),
    .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready & lane),
    .irq(irq8));

  wire        awready = lane ? awready8 : awready4;
  wire        wready  = lane ? wready8  : wready4;
  wire        bvalid  = lane ? bvalid8  : bvalid4;
  wire [1:0]  bresp   = lane ? bresp8   : bresp4;
  wire        arready = lane ? arready8 : arready4;
  wire        rvalid  = lane ? rvalid8  : rvalid4;
  wire [1:0]  rresp   = lane ? rresp8   : rresp4;
  wire [31:0] rdata   = lane ? rdata8   : rdata4;
  wire        irq     = lane ? irq8     : irq4;

  initial clk = 1'b0;
  always #5 clk = ~clk;

  // Edge counter: read at posedge+1, cyc is the number of the edge just taken.
  integer cyc;
  reg     started;
  always @(posedge clk) begin
    if (!started) cyc <= 0;
    else          cyc <= cyc + 1;
  end

  // irq rise monitor: rise_edge is the edge after which irq first read high.
  reg     irq_q;
  integer rise_edge;
  integer rise_cnt;
  reg     mon_clr;
  always @(posedge clk) begin
    if (mon_clr) begin
      irq_q     <= 1'b0;
      rise_cnt  <= 0;
      rise_edge <= -1;
    end else begin
      irq_q <= irq;
      if (irq && !irq_q) begin
        rise_cnt  <= rise_cnt + 1;
        rise_edge <= cyc;
      end
    end
  end

  integer passed;
  integer failed;
  reg [8*64-1:0] nonce;

  integer e, e2, a, s, base, expv, k, n, neff;
  reg [31:0] d;
  reg [1:0]  rr;
  reg [31:0] rd_data;
  reg [1:0]  rd_resp;
  integer    rd_edge;

  task check(input cond, input [8*64-1:0] msg);
    begin
      if (cond) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("lane %0d cyc %0d: %0s", lane, cyc, msg);
      end
    end
  endtask

  task tick;
    begin
      @(posedge clk);
      #1;
    end
  endtask

  task wait_cycles(input integer nc);
    integer i;
    begin
      for (i = 0; i < nc; i = i + 1) tick;
    end
  endtask

  task wait_until(input integer target);
    begin
      check(cyc <= target, "wait_until target not in the past");
      while (cyc < target) tick;
    end
  endtask

  task wait_rise(input integer b, input integer maxc);
    integer g;
    begin
      g = 0;
      while (rise_cnt == b && g < maxc) begin
        tick;
        g = g + 1;
      end
      check(rise_cnt == b + 1, "irq rose");
    end
  endtask

  // order: 0 AW and W together, 1 AW first, 2 W first. bdelay: BREADY low cycles.
  task axi_write(input [7:0] addr, input [31:0] data, input [3:0] strb,
                 input integer order, input integer bdelay, input [1:0] exp_resp,
                 output integer e_edge);
    reg aw_done, w_done, aw_fire, w_fire;
    reg [1:0] r;
    integer g, i;
    begin
      awaddr  = addr;
      wdata   = data;
      wstrb   = strb;
      aw_done = 1'b0;
      w_done  = 1'b0;
      awvalid = (order != 2);
      wvalid  = (order != 1);
      g = 0;
      while (!(aw_done && w_done) && g < 50) begin
        aw_fire = awvalid && awready;
        w_fire  = wvalid && wready;
        tick;
        g = g + 1;
        if (aw_fire) begin awvalid = 1'b0; aw_done = 1'b1; end
        if (w_fire)  begin wvalid  = 1'b0; w_done  = 1'b1; end
        if (aw_done && !w_done && !wvalid) begin
          check(!awready, "AWREADY low while address held");
          wvalid = 1'b1;
        end
        if (w_done && !aw_done && !awvalid) begin
          check(!wready, "WREADY low while data held");
          awvalid = 1'b1;
        end
        if (!(aw_done && w_done)) check(bvalid === 1'b0, "no B before both halves");
      end
      check(aw_done && w_done, "write handshakes completed");
      e_edge = cyc;
      check(bvalid === 1'b1, "BVALID after write completes");
      r = bresp;
      if (bresp !== exp_resp) $display("  addr %h bresp %b expected %b", addr, bresp, exp_resp);
      check(bresp === exp_resp, "BRESP value");
      for (i = 0; i < bdelay; i = i + 1) begin
        tick;
        check(bvalid === 1'b1 && bresp === r, "B held under backpressure");
        check(awready === 1'b0 && wready === 1'b0, "no write accepted while B waits");
      end
      bready = 1'b1;
      tick;
      bready = 1'b0;
      check(bvalid === 1'b0, "BVALID drops after BREADY");
    end
  endtask

  task axi_read(input [7:0] addr, input integer rdelay,
                output [31:0] data, output [1:0] resp, output integer a_edge);
    reg fire, done;
    integer g, i;
    begin
      araddr  = addr;
      arvalid = 1'b1;
      done    = 1'b0;
      g = 0;
      while (!done && g < 50) begin
        fire = arvalid && arready;
        tick;
        g = g + 1;
        if (fire) begin arvalid = 1'b0; done = 1'b1; end
      end
      check(done, "read address accepted");
      a_edge = cyc;
      check(rvalid === 1'b1, "RVALID after AR");
      data = rdata;
      resp = rresp;
      for (i = 0; i < rdelay; i = i + 1) begin
        tick;
        check(rvalid === 1'b1 && rdata === data && rresp === resp, "R held under backpressure");
        check(arready === 1'b0, "ARREADY low while R waits");
      end
      rready = 1'b1;
      tick;
      rready = 1'b0;
      check(rvalid === 1'b0, "RVALID drops after RREADY");
    end
  endtask

  task read_expect(input [7:0] addr, input [31:0] exp_data, input [1:0] exp_resp,
                   input [8*64-1:0] msg);
    begin
      axi_read(addr, 0, rd_data, rd_resp, rd_edge);
      if (rd_data !== exp_data || rd_resp !== exp_resp)
        $display("  read %h got %h/%b expected %h/%b", addr, rd_data, rd_resp, exp_data, exp_resp);
      check(rd_data === exp_data && rd_resp === exp_resp, msg);
    end
  endtask

  task wr(input [7:0] addr, input [31:0] data, input [3:0] strb, input [1:0] exp_resp);
    integer tmp;
    begin
      axi_write(addr, data, strb, 0, 0, exp_resp, tmp);
    end
  endtask

  task do_reset;
    begin
      aresetn = 1'b0;
      awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0; bready = 1'b0; rready = 1'b0;
      wait_cycles(3);
      check(bvalid === 1'b0 && rvalid === 1'b0, "no response valid in reset");
      check(irq === 1'b0, "irq low in reset");
      aresetn = 1'b1;
      tick;
      check(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, "ready after reset");
    end
  endtask

  task oneshot(input integer nl);
    begin
      neff = (nl == 0) ? 1 : nl;
      wr(8'h04, nl, 4'hF, OK);
      base = rise_cnt;
      axi_write(8'h00, 32'h3, 4'h1, 0, 0, OK, e);
      if (nl == 40) begin
        axi_read(8'h08, 0, d, rr, a);
        check(d == 40 - (a - 1 - e) && rr == OK, "COUNT read while counting");
      end
      wait_rise(base, neff + 20);
      if (rise_edge != e + neff) $display("  oneshot %0d: start %0d end %0d", nl, e, rise_edge);
      check(rise_edge == e + neff, "one-shot count timed to the cycle");
      read_expect(8'h00, 32'h2, OK, "EN clears itself after one-shot");
      read_expect(8'h08, 32'h0, OK, "COUNT 0 after one-shot");
      read_expect(8'h0C, 32'h1, OK, "EXPIRED set");
      wait_cycles(2 * neff + 5);
      check(rise_cnt == base + 1 && irq === 1'b1, "irq stays high until cleared");
      wr(8'h0C, 32'h1, 4'h1, OK);
      check(irq === 1'b0, "irq low after clear");
      read_expect(8'h0C, 32'h0, OK, "EXPIRED cleared");
      wait_cycles(2 * neff + 5);
      check(rise_cnt == base + 1 && irq === 1'b0, "no second interrupt in one-shot");
    end
  endtask

  task run_lane;
    begin
      do_reset;
      // 1. reset values
      read_expect(8'h00, 32'h0, OK, "CTRL reset value");
      read_expect(8'h04, 32'h0, OK, "LOAD reset value");
      read_expect(8'h08, 32'h0, OK, "COUNT reset value");
      read_expect(8'h0C, 32'h0, OK, "STATUS reset value");
      check(irq === 1'b0, "irq reset value");

      // 2. LOAD, strobes, channel orders, backpressure
      axi_write(8'h04, 32'hAABBCCDD, 4'hF, 0, 0, OK, e);
      axi_read(8'h04, 2, d, rr, a);
      check(d === 32'hAABBCCDD && rr === OK, "LOAD full write readback");
      axi_write(8'h04, 32'h11223344, 4'b0101, 1, 3, OK, e);
      read_expect(8'h04, 32'hAA22CC44, OK, "LOAD partial strobes, AW first");
      axi_write(8'h04, 32'h55667788, 4'b1010, 2, 2, OK, e);
      read_expect(8'h04, 32'h55227744, OK, "LOAD partial strobes, W first");
      axi_write(8'h04, 32'hFFFFFFFF, 4'b0000, 0, 0, OK, e);
      read_expect(8'h04, 32'h55227744, OK, "LOAD empty strobe");
      axi_read(8'h04, 5, d, rr, a);
      check(d === 32'h55227744 && rr === OK, "read under R backpressure");

      // read and write on the same clock
      check(awready && wready && arready, "idle before concurrent access");
      awaddr = 8'h04; wdata = 32'h00000099; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
      araddr = 8'h04; arvalid = 1'b1;
      tick;
      awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
      check(bvalid === 1'b1 && rvalid === 1'b1, "read and write on one clock both accepted");
      check(bresp === OK && rdata === 32'h55227744 && rresp === OK, "concurrent read sees value at acceptance");
      bready = 1'b1; rready = 1'b1;
      tick;
      bready = 1'b0; rready = 1'b0;
      check(bvalid === 1'b0 && rvalid === 1'b0, "concurrent responses retired");
      read_expect(8'h04, 32'h00000099, OK, "concurrent write took effect");

      // 3. COUNT read only, SLVERR policy
      axi_write(8'h08, 32'h1234, 4'hF, 0, 1, ERR, e);
      read_expect(8'h08, 32'h0, OK, "COUNT unchanged by write");
      axi_write(8'h05, 32'hFFFFFFFF, 4'hF, 1, 0, ERR, e);
      read_expect(8'h04, 32'h99, OK, "unaligned write changes nothing");
      axi_write(8'h01, 32'h7, 4'hF, 2, 0, ERR, e);
      read_expect(8'h00, 32'h0, OK, "unaligned CTRL write changes nothing");
      read_expect(8'h06, 32'h0, ERR, "unaligned read SLVERR");
      read_expect(8'h0D, 32'h0, ERR, "unaligned read SLVERR 2");
      if (lane) begin
        wr(8'h10, 32'h7, 4'hF, ERR);
        wr(8'h14, 32'h0, 4'hF, ERR);
        wr(8'h1C, 32'h1, 4'hF, ERR);
        wr(8'h84, 32'h0, 4'hF, ERR);
        wr(8'hF0, 32'h7, 4'hF, ERR);
        read_expect(8'h00, 32'h0, OK, "no alias of CTRL from 0x10 up");
        read_expect(8'h04, 32'h99, OK, "no alias of LOAD from 0x10 up");
        read_expect(8'h10, 32'h0, ERR, "read 0x10 SLVERR");
        read_expect(8'h14, 32'h0, ERR, "read 0x14 SLVERR");
        read_expect(8'h18, 32'h0, ERR, "read 0x18 SLVERR");
        read_expect(8'hF4, 32'h0, ERR, "read 0xF4 SLVERR");
        wait_cycles(5);
        read_expect(8'h08, 32'h0, OK, "no count started by unmapped write");
        check(irq === 1'b0, "no irq from unmapped write");
      end

      // 4. CTRL write without wstrb[0]
      axi_write(8'h00, 32'h7, 4'b1110, 0, 0, OK, e);
      read_expect(8'h00, 32'h0, OK, "CTRL unchanged without wstrb[0]");
      wait_cycles(3);
      read_expect(8'h08, 32'h0, OK, "no count without wstrb[0]");

      // 5. one-shot timing
      oneshot(5);
      oneshot(1);
      oneshot(0);
      oneshot(40);

      // 6. interrupt enable on a pending expiry; STATUS write rules
      wr(8'h04, 32'h3, 4'hF, OK);
      axi_write(8'h00, 32'h1, 4'h1, 0, 0, OK, e);
      wait_cycles(10);
      check(irq === 1'b0, "no irq with IE 0");
      read_expect(8'h0C, 32'h1, OK, "EXPIRED set with IE 0");
      read_expect(8'h00, 32'h0, OK, "EN cleared, IE 0");
      wr(8'h0C, 32'h0, 4'hF, OK);
      read_expect(8'h0C, 32'h1, OK, "STATUS write 0 keeps EXPIRED");
      wr(8'h0C, 32'h1, 4'b1110, OK);
      read_expect(8'h0C, 32'h1, OK, "STATUS write without wstrb[0] keeps EXPIRED");
      base = rise_cnt;
      axi_write(8'h00, 32'h2, 4'h1, 0, 0, OK, e);
      check(irq === 1'b1, "irq high after IE on pending");
      check(rise_cnt == base + 1 && rise_edge == e, "irq rises at once with IE");
      wr(8'h00, 32'h0, 4'h1, OK);
      check(irq === 1'b0, "irq low when IE written 0");
      read_expect(8'h0C, 32'h1, OK, "EXPIRED kept when IE written 0");
      wr(8'h0C, 32'h1, 4'h1, OK);
      read_expect(8'h0C, 32'h0, OK, "EXPIRED cleared");

      // 7. periodic over several periods, clear on the end edge, stop
      wr(8'h04, 32'd20, 4'hF, OK);
      base = rise_cnt;
      axi_write(8'h00, 32'h7, 4'h1, 0, 0, OK, e);
      for (k = 1; k <= 4; k = k + 1) begin
        wait_rise(base + k - 1, 30);
        if (rise_edge != e + 20 * k) $display("  periodic k=%0d start %0d end %0d", k, e, rise_edge);
        check(rise_edge == e + 20 * k, "periodic count timed to the cycle");
        read_expect(8'h00, 32'h7, OK, "EN stays 1 in periodic");
        wr(8'h0C, 32'h1, 4'h1, OK);
        check(irq === 1'b0, "periodic expiry cleared");
      end
      wait_until(e + 99);
      check(cyc == e + 99, "positioned before end edge");
      axi_write(8'h0C, 32'h1, 4'h1, 0, 0, OK, e2);
      check(e2 == e + 100, "clear lands on the end edge");
      check(rise_cnt == base + 5 && rise_edge == e + 100, "5th period timed");
      check(irq === 1'b1, "count end beats clear: irq");
      read_expect(8'h0C, 32'h1, OK, "count end beats clear: EXPIRED");
      wr(8'h0C, 32'h1, 4'h1, OK);
      wait_rise(base + 5, 30);
      check(rise_edge == e + 120, "6th period timed");
      wr(8'h0C, 32'h1, 4'h1, OK);
      axi_write(8'h00, 32'h6, 4'h1, 0, 0, OK, s);
      expv = 20 - (s - (e + 120));
      read_expect(8'h08, expv, OK, "COUNT at stop");
      read_expect(8'h00, 32'h6, OK, "CTRL after stop");
      wait_cycles(45);
      check(rise_cnt == base + 6 && irq === 1'b0, "no expiry after stop");
      read_expect(8'h08, expv, OK, "COUNT frozen after stop");

      // 8. restart
      base = rise_cnt;
      axi_write(8'h00, 32'h3, 4'h1, 0, 0, OK, e);
      wait_cycles(8);
      axi_write(8'h00, 32'h3, 4'h1, 0, 0, OK, e2);
      wait_rise(base, 40);
      check(rise_edge == e2 + 20, "restart counts from LOAD");
      wait_cycles(30);
      check(rise_cnt == base + 1, "single expiry after restart");
      read_expect(8'h00, 32'h2, OK, "EN cleared after restarted one-shot");
      wr(8'h0C, 32'h1, 4'h1, OK);

      // 9. CTRL write on the end edge: EN 1 restarts, EN 0 stops
      wr(8'h04, 32'd10, 4'hF, OK);
      base = rise_cnt;
      axi_write(8'h00, 32'h3, 4'h1, 0, 0, OK, e);
      wait_until(e + 9);
      axi_write(8'h00, 32'h3, 4'h1, 0, 0, OK, e2);
      check(e2 == e + 10, "CTRL write lands on end edge");
      check(rise_cnt == base + 1 && rise_edge == e + 10, "EXPIRED set by ending count");
      read_expect(8'h00, 32'h3, OK, "write wins: EN 1");
      wr(8'h0C, 32'h1, 4'h1, OK);
      wait_rise(base + 1, 20);
      check(rise_edge == e2 + 10, "restart on end edge timed");
      read_expect(8'h00, 32'h2, OK, "EN cleared after count");
      wr(8'h0C, 32'h1, 4'h1, OK);
      base = rise_cnt;
      axi_write(8'h00, 32'h3, 4'h1, 0, 0, OK, e);
      wait_until(e + 9);
      axi_write(8'h00, 32'h2, 4'h1, 0, 0, OK, e2);
      check(e2 == e + 10, "stop lands on end edge");
      check(rise_cnt == base + 1 && rise_edge == e + 10, "EXPIRED set on stop edge");
      read_expect(8'h00, 32'h2, OK, "write wins: EN 0");
      read_expect(8'h08, 32'h0, OK, "COUNT from end edge");
      wr(8'h0C, 32'h1, 4'h1, OK);

      // 10. reset during a count
      wr(8'h04, 32'd50, 4'hF, OK);
      axi_write(8'h00, 32'h7, 4'h1, 0, 0, OK, e);
      wait_cycles(10);
      do_reset;
      read_expect(8'h00, 32'h0, OK, "CTRL after reset in count");
      read_expect(8'h04, 32'h0, OK, "LOAD after reset in count");
      read_expect(8'h08, 32'h0, OK, "COUNT after reset in count");
      base = rise_cnt;
      wait_cycles(60);
      check(rise_cnt == base && irq === 1'b0, "no expiry after reset");
      read_expect(8'h0C, 32'h0, OK, "STATUS after reset in count");
    end
  endtask

  initial begin
    passed = 0; failed = 0; started = 1'b0; mon_clr = 1'b1; lane = 1'b0; aresetn = 1'b0;
    awaddr = 8'h0; awvalid = 1'b0; wdata = 32'h0; wstrb = 4'h0; wvalid = 1'b0; bready = 1'b0;
    araddr = 8'h0; arvalid = 1'b0; rready = 1'b0;
    tick;
    started = 1'b1;
    mon_clr = 1'b0;
    lane = 1'b0;
    run_lane;
    aresetn = 1'b0;
    tick;
    lane = 1'b1;
    run_lane;
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  initial begin
    #2000000;
    failed = failed + 1;
    $error("timeout");
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule
